SELECT json_build_object('surveys',(SELECT json_agg(s) FROM surveys s),'scores',(SELECT json_agg(s) FROM scores s),'risks',(SELECT json_agg(r) FROM "riskRatings" r),'assessments',(SELECT json_agg(a) FROM "complianceAssessments" a WHERE "surveyId"=1),'checks',(SELECT json_agg(e) FROM "complianceEvidenceChecks" e JOIN "complianceAssessments" a USING ("complianceAssessmentId") WHERE a."surveyId"=1),'compliances',(SELECT json_agg(c) FROM compliances c),'evidence',(SELECT json_agg(e) FROM evidence e));
